 return `${drainEffectiveMarkup(r)}<p><strong>轮换状态：${r.enabled?esc(phase):'定时轮换已暂停，故障切换保留'}</strong> · 当前承载 ${esc(r.active_name)}<br>下次 DNS 切换：${esc(new Date(r.next_switch_at*1000).toLocaleString())}<br><strong>轮换倒计时：${countdown}</strong><br>${esc(r.status||'等待执行')}</p>${rotationTimingMarkup(r)}${rotationDrainMarkup(r)}`;
