 const transition=t?`<p>DNS #${esc(t.binding_id)}：VPS #${esc(t.from_server_id??'未记录')} / ${esc(t.from_ip??'未记录')} → VPS #${esc(t.to_server_id??'未记录')} / ${esc(t.to_ip??'未记录')}<br>提交：${esc(rotationAuditTime(t.submitted_at))}<br>回读确认：${esc(rotationAuditTime(t.confirmed_at))} · TTL ${esc(t.ttl_s??'未记录')} 秒</p>`:'';
